function ratingDetail(ratings) {
  const raw = {};
  for (let rating = 1; rating <= 5; rating += 1) {
    raw[String(rating)] = (ratings.filter((value) => value === rating).length / ratings.length) * 100;
  }
  const detail = Object.fromEntries(Object.entries(raw).map(([key, value]) => [key, Math.floor(value)]));
  let remainder = 100 - Object.values(detail).reduce((sum, value) => sum + value, 0);
  for (const key of Object.keys(raw).sort((left, right) => (raw[right] - detail[right]) - (raw[left] - detail[left]))) {
    if (remainder <= 0) break;
    detail[key] += 1;
    remainder -= 1;
  }
  return detail;
}

function defaultSizes(category, subCategory) {
  if (category === "Footwear") return ["6", "7", "8", "9", "10", "11", "12"];
  if (category === "Bags" || category === "Accessories") return ["One Size"];
  if (subCategory === "Shorts" || subCategory === "Pants" || subCategory === "Jeans") return ["XS", "S", "M", "L", "XL", "XXL"];
  return ["XS", "S", "M", "L", "XL"];
}

function evidenceValue(attributes, key) {
  const value = attributes[key];
  if (attributeTypes[key] === "number") return { evidenceValueNumber: Number(value) };
  if (attributeTypes[key] === "boolean") return { evidenceValueBoolean: Boolean(value) };
  return { evidenceValueText: String(value) };
}

