const products = [];
const reviews = [];
const reviewProfiles = [];
const reviewEvidence = [];
let reviewId = START_REVIEW_ID;
let evidenceId = START_EVIDENCE_ID;

for (const [index, source] of productsSource.entries()) {
  const id = START_PRODUCT_ID + index;
  const ratings = source.reviews.map((review) => review.rating);
  const product = {
    id,
    name: source.name,
    keyword: source.keyword,
    category: source.category,
    subCategory: source.subCategory,
    price: source.price,
    rating: Number((ratings.reduce((sum, rating) => sum + rating, 0) / ratings.length).toFixed(1)),
    reviewCount: source.reviews.length,
    ratingDetail: ratingDetail(ratings),
    img: `https://loremflickr.com/600/600/${source.imageTags}?lock=${50000 + id}`,
    brandStory: brandStories[source.attributes.brand],
    desc: source.desc,
    sizes: source.sizes ?? defaultSizes(source.category, source.subCategory),
    colors: source.colors,
    features: source.features,
    descImages: [`https://loremflickr.com/600/800/${source.imageTags},detail?lock=${60000 + id}`],
    brandImages: [`https://loremflickr.com/1200/400/${source.attributes.brand},fashion?lock=${70000 + id}`],
    Material: source.attributes.material,
    attributes: source.attributes,
  };
  products.push(product);

  for (const review of source.reviews) {
    const currentReviewId = reviewId++;
    const comment = review.evidence.map(([text]) => text).join(" ");
    reviews.push({
      id: currentReviewId,
      productId: id,
      userName: `V4 Reviewer ${currentReviewId}`,
      rating: review.rating,
      date: "2026-05-29",
      title: `${review.title} for ${source.name}`,
      comment,
      helpfulVotes: (currentReviewId * 7) % 31,
      verifiedPurchase: currentReviewId % 6 !== 0,
      reviewSource: "synthetic_demo",
      reviewImagesCount: currentReviewId % 9 === 0 ? 1 : 0,
    });

    const [gender, heightCm, bodyType, usualSize, purchasedSize, fitResult] = review.profile;
    reviewProfiles.push({ reviewId: currentReviewId, gender, heightCm, bodyType, usualSize, purchasedSize, fitResult });

    for (const [text, attributeKey, sentiment, issueType, severity] of review.evidence) {
      reviewEvidence.push({
        id: evidenceId++,
        reviewId: currentReviewId,
        productId: id,
        attributeKey,
        sentiment,
        issueType,
        severity,
        evidenceText: text,
        source: "codex-v4",
        humanReviewStatus: "generated",
        ...evidenceValue(source.attributes, attributeKey),
      });
    }
  }
}

if (products.length !== 50) {
  throw new Error(`Expected 50 products, got ${products.length}.`);
}
if (reviews.length !== 250 || reviewProfiles.length !== 250 || reviewEvidence.length !== 500) {
  throw new Error("Unexpected review/profile/evidence counts.");
}

const batch = {
  batchId: "batch-v4-002",
  authoredBy: "codex",
  authoredAt: "2026-06-01",
  notes: "Amazon AI-ready v4 cumulative seed batch. Product names, descriptions, review sentences, and evidence sentences were directly authored by Codex without Gemini, external LLM APIs, or rule-based sentence generation. This script only expands IDs, ratingDetail, image URLs, profiles, and typed evidence value fields.",
  products,
  reviews,
  reviewProfiles,
  reviewEvidence,
};

const currentDir = dirname(fileURLToPath(import.meta.url));
const outputPath = resolve(currentDir, "../fixtures/amazon-human/seed/batch-v4-002.json");
mkdirSync(dirname(outputPath), { recursive: true });
writeFileSync(outputPath, `${JSON.stringify(batch, null, 2)}\n`, "utf-8");
console.log(`Wrote ${outputPath}`);
console.log(`Products: ${products.length}, reviews: ${reviews.length}, evidence: ${reviewEvidence.length}`);
